function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*15485867+17);var genes=['scheduler','checkpoint','router','encoder','auditor','planner','simulator','indexer','validator','composer','monitor','gateway'];function genome(){var g={};genes.forEach(function(x){g[x]=+(R()).toFixed(2);});return g;}var A=genome(),B=genome(),dot=0,na=0,nb=0,shared=0;genes.forEach(function(x){dot+=A[x]*B[x];na+=A[x]*A[x];nb+=B[x]*B[x];if(A[x]>0.5&&B[x]>0.5)shared++;});var sim=dot/(Math.sqrt(na)*Math.sqrt(nb));return{genes:genes.length,cosine_similarity:+sim.toFixed(3),shared_strong_genes:shared,compatibility:sim>0.6?'compose':'review-first'};}
var SEED = 81001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

